use vstd::prelude::*;

verus! {

    // A factor divides a candidate if and only if candidate % factor == 0
    spec fn divides(factor: nat, candidate: nat) -> bool {
        candidate % factor == 0
    }

    // A natural number > 1 is prime iff it has no divisors in (1, candidate)
    spec fn is_prime(candidate: nat) -> bool {
        candidate > 1
        && forall f: nat :: 1 < f < candidate ==> !divides(f, candidate)
    }

    // Naive trial‐division primality test
    //
    // We assume candidate > 1.  We return `true` exactly when
    // is_prime(candidate as nat) holds.
    fn test_prime(candidate: u64) -> (result: bool)
        requires
            candidate > 1
        ensures
            result == is_prime(candidate as nat)
    {
        // try every f = 2,3,...,candidate-1
        let mut f: u64 = 2;
        while f < candidate
            invariant
                // bounds on the loop index
                2 <= f <= candidate,
                // up to (but not including) f no divisor was found:
                forall d: nat :: 1 < d < (f as nat) ==> !divides(d, candidate as nat)
            decreases
                candidate - f
        {
            if candidate % f == 0 {
                proof {
                    // We have found a divisor f in 2..candidate-1
                    assert(divides(f as nat, candidate as nat));
                    // hence the forall in is_prime fails, so !is_prime
                    assert(!is_prime(candidate as nat));
                }
                return false;
            }
            f = f + 1;
        }

        // if we exit the loop, no divisors were found in 2..candidate-1
        proof {
            assert(is_prime(candidate as nat));
        }
        true
    }
}

